import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),R=require('../../nell-research');
export async function research(p,base){for(const t of R.tasks){await p.goto(base+'nell-research.html');await p.locator('[data-case="'+t.id+'"] [data-research-place]').click();await p.locator('[data-research-visit="'+t.id+'"]').click();await p.getByRole('link',{name:'Compare this place’s evidence in my notebook'}).click();for(let i=0;i<3;i++){const section=p.locator('[data-case="'+t.id+'"]'),st=t.steps[i];if(st.type==='order'){const form=section.locator('[data-research-order]');for(let target=0;target<st.order.length;target++){for(;;){const order=await form.locator('[data-evidence-index]').evaluateAll(rows=>rows.map(r=>Number(r.dataset.evidenceIndex)));if(order.indexOf(st.order[target])===target)break;await form.locator('[data-evidence-index="'+st.order[target]+'"] [data-order-up]').click();}}await form.getByRole('button',{name:'Check my evidence order'}).click();}else{if(i===0){const rev=await p.evaluate(()=>HoneybrookNellCase.read().revision);await section.locator('[data-research-answer="'+((st.answer+1)%3)+'"]').click();await p.waitForFunction(()=>document.querySelector('#nellResearchApp [role=status]').textContent.startsWith('Paws and ponder'));assert.equal(await p.evaluate(()=>HoneybrookNellCase.read().revision),rev);}await section.locator('[data-research-answer="'+st.answer+'"]').click();}await p.waitForFunction(({id,step})=>HoneybrookNellCase.read().files[id]?.step===step,{id:t.id,step:i+1});if(i===1)await p.reload();}assert.match(await p.locator('[data-case="'+t.id+'"]').textContent(),/✓/);assert.equal(await p.evaluate(()=>HoneybrookNell.snapshot().haroldMet),false);}assert.equal(await p.evaluate(()=>HoneybrookNellCase.complete()),true);await p.getByRole('link',{name:'Return to my story · choose when to speak'}).click();}
